from __future__ import annotations

from datetime import date, datetime
from pathlib import Path

import click
from rich.console import Console
from rich.table import Table
from rich.text import Text

from todo_cli.db import Priority, Todo, add_todo, delete_todo, get_connection, list_todos, mark_done

console = Console()

PRIORITY_COLORS = {
    Priority.HIGH: "red",
    Priority.MEDIUM: "yellow",
    Priority.LOW: "green",
}


def _parse_date(value: str) -> date:
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m/%d"):
        try:
            parsed = datetime.strptime(value, fmt)
            if fmt == "%m/%d":
                parsed = parsed.replace(year=date.today().year)
            return parsed.date()
        except ValueError:
            continue
    raise click.BadParameter(f"Cannot parse date: {value!r}. Use YYYY-MM-DD format.")


class DateType(click.ParamType):
    name = "date"

    def convert(self, value, param, ctx):
        if isinstance(value, date):
            return value
        try:
            return _parse_date(value)
        except click.BadParameter:
            self.fail(f"Cannot parse date: {value!r}. Use YYYY-MM-DD format.", param, ctx)


DATE = DateType()


@click.group()
@click.option("--db", type=click.Path(path_type=Path), default=None, envvar="TODO_DB_PATH", help="Path to SQLite database.")
@click.pass_context
def cli(ctx: click.Context, db: Path | None) -> None:
    """A simple command-line todo list manager."""
    ctx.ensure_object(dict)
    ctx.obj["db_path"] = db


def _get_conn(ctx: click.Context):
    db_path = ctx.obj.get("db_path")
    if db_path:
        return get_connection(db_path)
    return get_connection()


@cli.command()
@click.argument("title")
@click.option("-p", "--priority", type=click.Choice(["high", "medium", "low"], case_sensitive=False), default="medium", help="Task priority.")
@click.option("-d", "--due", type=DATE, default=None, help="Due date (YYYY-MM-DD).")
@click.pass_context
def add(ctx: click.Context, title: str, priority: str, due: date | None) -> None:
    """Add a new todo item."""
    conn = _get_conn(ctx)
    todo = add_todo(conn, title, Priority(priority.lower()), due)
    conn.close()
    console.print(f"Added todo [bold]#{todo.id}[/bold]: {todo.title}")


def _render_todo_table(todos: list[Todo]) -> Table:
    table = Table(show_header=True, header_style="bold")
    table.add_column("ID", style="dim", width=4)
    table.add_column("Title")
    table.add_column("Priority", width=8)
    table.add_column("Due", width=12)
    table.add_column("Status", width=8)

    today = date.today()

    for todo in todos:
        priority_text = Text(todo.priority.value, style=PRIORITY_COLORS[todo.priority])

        if todo.due_date:
            due_text = Text(todo.due_date.isoformat())
            if not todo.done and todo.due_date < today:
                due_text.stylize("bold red")
            elif not todo.done and todo.due_date == today:
                due_text.stylize("bold yellow")
        else:
            due_text = Text("-", style="dim")

        status = Text("done", style="green") if todo.done else Text("pending", style="dim")

        title_style = "strike dim" if todo.done else ""
        title_text = Text(todo.title, style=title_style)

        table.add_row(str(todo.id), title_text, priority_text, due_text, status)

    return table


@cli.command("list")
